//! `body_of` — The body of a vendored file — everything after the first (stamp) line, which is what the stamp's sha256 covers.

/// The body of a vendored file — everything after the first (stamp) line, which is what the stamp's
/// sha256 covers.
pub(crate) fn body_of(content: &str) -> &str {
    content.find('\n').map(|i| &content[i + 1..]).unwrap_or("")
}
